import { existsSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { REPORT_STATUS } from '../../.claude/skills/report-results/scripts/report-contract.ts';
import { readEnv, requireEnv, runGit, setOutput } from './lib/actions.ts';
import { decidePublishStatus, isFailingStatus, type PublishState } from './lib/publish-status.ts';
import { findDisallowedChanges, formatDisallowedChange, type DisallowedChange } from './lib/test-paths.ts';

const BOT_NAME = 'github-actions[bot]';
const BOT_EMAIL = '41898282+github-actions[bot]@users.noreply.github.com';
const COMMIT_TITLE = 'test: add unit tests generated by Unit Test Agent';

function applyPatch(patchFile: string): DisallowedChange[] {
  runGit('apply', '--index', patchFile);
  return findDisallowedChanges(runGit('diff', '--cached', '--raw', '--no-abbrev'));
}

function commitAndPush(headRef: string, runUrl: string): string {
  runGit('config', 'user.name', BOT_NAME);
  runGit('config', 'user.email', BOT_EMAIL);
  runGit('commit', '--quiet', '--message', COMMIT_TITLE, '--message', `Verified by workflow run ${runUrl}`);
  runGit('push', 'origin', `HEAD:refs/heads/${headRef}`);
  return runGit('rev-parse', 'HEAD').trim();
}

const patchFile = join(requireEnv('ARTIFACTS_DIR'), 'agent-output', 'tests.patch');
const stateFile = requireEnv('PUBLISH_STATE_FILE');
const headSha = requireEnv('HEAD_SHA');
const headRef = requireEnv('HEAD_REF');
const runUrl = `${requireEnv('GITHUB_SERVER_URL')}/${requireEnv('GITHUB_REPOSITORY')}/actions/runs/${requireEnv('GITHUB_RUN_ID')}`;

const hasPatch = readEnv('HAS_PATCH') === 'true' && existsSync(patchFile);
const branchMoved = runGit('rev-parse', 'HEAD').trim() !== headSha;
const disallowedChanges = hasPatch && !branchMoved ? applyPatch(patchFile) : [];

const status = decidePublishStatus({
  generateResult: readEnv('GENERATE_RESULT'),
  verifyResult: readEnv('VERIFY_RESULT'),
  testableSources: Number(readEnv('TESTABLE')),
  hasPatch,
  branchMoved,
  disallowedChanges: disallowedChanges.length,
});

const state: PublishState = {
  status,
  commit: status === REPORT_STATUS.COMMITTED ? commitAndPush(headRef, runUrl) : '',
  rejectedPaths: disallowedChanges.map(formatDisallowedChange),
};

writeFileSync(stateFile, JSON.stringify(state));
setOutput('status', status);
setOutput('failed', String(isFailingStatus(status)));
